def k6_star__ref(n):
    qc = QuantumCircuit(n)
    qc.h(0)
    for i in range(1, n):
        qc.cx(0, i)
    return qc


def k6_star__st_shift(n):
    qc = QuantumCircuit(n)
    qc.h(0)
    for j in range(2, n + 1):
        qc.cx(0, j - 1)
    return qc


def k6_star__st_helper(n):
    qc = QuantumCircuit(n)
    k6_star__st_helper_layers(qc, n)
    return qc


def k6_star__st_helper_layers(qc, n):
    qc.h(0)
    for i in range(1, n):
        qc.cx(0, i)


