def k6_out_tree__ref(n):
    qc = QuantumCircuit(n)
    qc.h(0)
    k = 1
    while k < n:
        for j in range(0, min(k, n - k)):
            qc.cx(j, j + k)
        k *= 2
    return qc


def k6_out_tree__st_self(n):
    qc = QuantumCircuit(n)
    qc.h(0)
    k = 1
    while k < n:
        for j in range(0, min(k, n - k)):
            qc.cx(j, j + k)
        k *= 2
    return qc


def k6_out_w__ref(n):
    qc = QuantumCircuit(n)
    qc.x(0)
    for i in range(n - 1):
        qc.ry(2 * math.acos(math.sqrt(1 / (n - i))), i + 1)
        qc.cx(i + 1, i)
        qc.cx(i, i + 1)
    return qc


def k6_out_w__st_self(n):
    qc = QuantumCircuit(n)
